/* Photo first, the phone's own font, night mode (ADR 0025). */
.card { background:#fff; }
.card.nightMode, .card.night_mode { background:#1c1c1e; }
.av { --ink:#111; --sub:#5f6368; --bg:#fff;
  font-family:-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  font-size:17px; line-height:1.45; color:var(--ink); max-width:560px; margin:0 auto; padding:20px 16px 28px; text-align:left; }
.nightMode .av, .night_mode .av { --ink:#f1f1f1; --sub:#a0a4a8; --bg:#1c1c1e; }
.av a { color:inherit; }
.prompt { font-size:.8em; font-weight:600; letter-spacing:.06em; text-transform:uppercase; color:var(--sub); margin:0 0 10px; }
.photo img { display:block; width:100%; height:auto; max-height:46vh; object-fit:contain; border-radius:10px; }
.photo img + img { margin-top:8px; }
.sound { margin:10px 0; }
.names { margin:14px 0 10px; }
.name { font-size:1.6em; font-weight:700; letter-spacing:-.01em; line-height:1.15; }
.sci { font-style:italic; color:var(--sub); font-size:.92em; margin-top:1px; }
/* Unused until the names change (ADR 0025): the outlined "IOC <name>" tag above .name. */
.ioc-tag { display:inline-block; font-size:10.5px; line-height:1; color:var(--sub);
  border:1px solid color-mix(in srgb, var(--sub) 55%, transparent); border-radius:999px; padding:2px 7px; margin:0 0 3px; }
.ioc-tag b { font-weight:700; letter-spacing:.08em; margin-right:3px; }
.credits { font-size:11.5px; line-height:1.4; color:var(--sub); margin-top:16px; padding-top:8px;
  border-top:1px solid color-mix(in srgb, var(--sub) 35%, transparent); }
.credits a { text-decoration:underline; }

